import React, { useState, useEffect } from 'react';
import { getUsers, deleteUser, updateUser } from '../services/api';

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingUser, setEditingUser] = useState(null);
  const [updatedRole, setUpdatedRole] = useState('');

  useEffect(() => {
    const fetchUsers = async () => {
      setLoading(true);
      try {
        const response = await getUsers();
        if (response && Array.isArray(response.data)) {
          setUsers(response.data);
          setError(null);
        } else {
          setError('Invalid user data format.');
        }
      } catch (error) {
        console.error('Error fetching users:', error);
        setError('Error fetching users. Please try again later.');
      } finally {
        setLoading(false);
      }
    };
    fetchUsers();
  }, []);

  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId);
      setUsers(users.filter(user => user._id !== userId));
    } catch (error) {
      console.error('Error deleting user:', error);
      setError('Error deleting user. Please try again later.');
    }
  };

  const handleUpdate = async (userId, updatedData) => {
    if (!['user', 'admin'].includes(updatedData.role)) {
      setError('Invalid role selected.');
      return;
    }

    setError(null);
    try {
      const updatedUser = await updateUser(userId, updatedData);
      setUsers(users.map(user => user._id === userId ? updatedUser.data : user));
      setEditingUser(null);
    } catch (error) {
      console.error('Error updating user:', error);
      setError('Error updating user. Please try again later.');
    }
  };

  const handleRoleChange = (e) => {
    setUpdatedRole(e.target.value);
  };

  const openEditForm = (user) => {
    setEditingUser(user);
    setUpdatedRole(user.role);
  };

  const closeEditForm = () => {
    setEditingUser(null);
    setUpdatedRole('');
  };

  return (
    <div>
      <h1>User Management</h1>
      {loading && <p>Loading users...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}

      {users?.length > 0 ? (
        <table>
          <thead>
            <tr>
              <th>Username</th>
              <th>Role</th>
              <th>Franchise</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map(user => (
              <tr key={user._id}>
                <td>{user.username}</td>
                <td>{user.role}</td>
                <td>{user.franchise?.name || 'N/A'}</td>
                <td>
                  <button onClick={() => openEditForm(user)}>Edit</button>
                  <button onClick={() => handleDelete(user._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No users found.</p>
      )}

      {editingUser && (
        <div className="edit-form">
          <h2>Edit User</h2>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              handleUpdate(editingUser._id, { role: updatedRole });
            }}
          >
            <div>
              <label htmlFor="username">Username:</label>
              <input
                id="username"
                type="text"
                value={editingUser.username}
                readOnly
              />
            </div>
            <div>
              <label htmlFor="role">Role:</label>
              <select
                id="role"
                value={updatedRole}
                onChange={handleRoleChange}
              >
                <option value="user">User</option>
                <option value="admin">Admin</option>
              </select>
            </div>
            <div>
              <button type="submit">Save Changes</button>
              <button type="button" onClick={closeEditForm}>Cancel</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default UserManagement;
